import { decode, encode } from './lib/bencode/index.mjs';
import { CliParseError, formatError, getHelp, getProgramName, parseCommandLine } from './lib/cli/index.mjs';
import { AsciiEncodeError, bytesFromAscii, encodeAscii, formatAsciiTraceback } from './lib/python/bytes.mjs';
import { stringRepr, toPythonRepr } from './lib/python/repr.mjs';

function main(argv) {
  const programName = getProgramName(argv);

  try {
    const result = parseCommandLine(argv, parsePythonInt);

    if (result.kind === 'help') {
      process.stdout.write(`${getHelp(programName)}\n`);
      return;
    }

    const listData = [encodeAscii(result.values.a), result.values.b, [result.values.b]];
    const encoded = encode(listData);
    const decoded = decode(encoded);

    process.stdout.write(`${toPythonRepr(bytesFromAscii(encoded))}\n`);
    process.stdout.write(`${toPythonRepr(decoded)}\n`);
  } catch (error) {
    if (error instanceof CliParseError) {
      process.stderr.write(`${formatError(programName, error.message)}\n`);
      process.exitCode = 2;
      return;
    }

    if (error instanceof InvalidPythonIntError) {
      process.stderr.write(`${formatError(programName, `argument --b: invalid int value: ${stringRepr(error.rawValue)}`)}\n`);
      process.exitCode = 2;
      return;
    }

    if (error instanceof AsciiEncodeError) {
      process.stderr.write(`${formatAsciiTraceback(error)}\n`);
      process.exitCode = 1;
      return;
    }

    throw error;
  }
}

class InvalidPythonIntError extends Error {
  constructor(rawValue) {
    super(`Invalid Python int value: ${rawValue}`);
    this.name = 'InvalidPythonIntError';
    this.rawValue = rawValue;
  }
}

function parsePythonInt(rawValue) {
  if (!/^[+-]?(?:0|[0-9](?:_?[0-9])*)$/.test(rawValue)) {
    throw new InvalidPythonIntError(rawValue);
  }

  const normalized = rawValue.replace(/_/g, '');

  try {
    return BigInt(normalized);
  } catch {
    throw new InvalidPythonIntError(rawValue);
  }
}

main(process.argv);

